                const candidate = keys.get(candidateKey);
                if (candidate === content) {
                    return candidateKey; // This exact content already has a numbered key
                }
                counter++;
                candidateKey = `${baseKey}${counter}`;
            }
            keys.set(candidateKey, content);
            return candidateKey;
        }
