  namespaces.forEach((ns, i) => {
    const nameToUse = getVarName(ns.name)
    if (nameToUse !== ns.name) {
      toc += `\n  ${quoteChar}${ns.name}${quoteChar}: ${nameToUse}`
    } else {
      toc += `\n  ${ns.name}`
    }
