const pwd = process.cwd();

const { createJiti } = await import("./jiti.cjs");

const jiti = createJiti(pwd);

const resolved = (process.argv[1] = jiti.resolve(resolve(pwd, script)));

await jiti.import(resolved).catch((error) => {
