import i18n from "i18next";
import HttpBackend from "i18next-http-backend";
import LanguageDetector from "i18next-browser-languagedetector";
import { initReactI18next } from "react-i18next";

// The English catalog is bundled so the first paint is always real copy —
// never a flash of raw key paths — and doubles as the fallback. Other locales
// are fetched from public/locales at runtime.
import en from "../public/locales/en/translation.json";

export const SUPPORTED_LANGUAGES = ["en", "fr", "es", "de"];

i18n
  .use(HttpBackend)
  .use(LanguageDetector)
  .use(initReactI18next)
  .init({
    fallbackLng: "en",
    supportedLngs: SUPPORTED_LANGUAGES,
    // One coarse namespace; split only when a route's copy is big enough to
    // be worth a separate request.
    ns: ["translation"],
    defaultNS: "translation",
    resources: { en: { translation: en } },
    partialBundledLanguages: true,
    backend: { loadPath: "/locales/{{lng}}/{{ns}}.json" },
    detection: {
      order: ["querystring", "localStorage", "navigator"],
      lookupQuerystring: "lang",
      caches: ["localStorage"],
    },
    interpolation: { escapeValue: false }, // React already escapes
    // Report keys that reach the runtime without a catalog entry, in dev only.
    saveMissing: import.meta.env?.DEV ?? false,
    missingKeyHandler: (lngs, ns, key) =>
      console.warn(`[i18n] missing key "${key}" in ${ns} (${lngs.join(", ")})`),
    react: {
      // English is bundled, so there is nothing to suspend on at first paint;
      // switching locale re-renders when the catalog arrives.
      useSuspense: false,
    },
  });

export default i18n;

