        /* c8 ignore start */
        if (n.length === 1) {
          acc = combine(
            acc,
            pre + n[0],
            [''],
            max,
            maxLength,
            dropEmpties && !m.post.length,
          )
          if (!m.post.length) break
          str = m.post
          continue
        }
        /* c8 ignore stop */
