    // stripped) and log-sanitised (CR/LF/control chars replaced) to prevent
    // leaking credentials that may have been embedded in loadPath and to
    // prevent log forging via crafted `lng`/`ns` values (CWE-117).
    const safeUrl = sanitizeLogValue(redactUrlCredentials(url))
    this.options.request(this.options, url, payload, (err, res) => {
      if (res && ((res.status >= 500 && res.status < 600) || !res.status)) return callback('failed loading ' + safeUrl + '; status code: ' + res.status, true /* retry */)
      if (res && res.status >= 400 && res.status < 500) return callback('failed loading ' + safeUrl + '; status code: ' + res.status, false /* no retry */)
      if (!res && err && err.message) {
        const errorMessage = err.message.toLowerCase()
        // for example:
        // Chrome: "Failed to fetch"
        // Firefox: "NetworkError when attempting to fetch resource."
        // Safari: "Load failed"
        const isNetworkError = [
          'failed',
          'fetch',
          'network',
          'load'
