android {
    namespace 'com.northwind'
    compileSdk 34

    // Per-app language picker (system settings lists the app's locales). AGP 8.1+.
    androidResources {
        generateLocaleConfig true
    }

    // Localization gaps and hardcoded literals fail silently at runtime otherwise:
    // a missing fr string falls back to English instead of erroring.
    lint {
        error += ['HardcodedText', 'MissingTranslation']
    }
}

